+/**
+ * Resamples an array after repeatedly smoothing alternating interior points.
+ * The direct resampler is used when no additional smoothing is needed.
+ */
+export function arraySmoothingResample(input: number[], points: number): number[] {
+    if (input.length === points) return input;
+
+    let samples = input;
+    while (samples.length > points * 2) {
+        const smoothed: number[] = [];
+        for (let i = 1; i < samples.length - 1; i += 2) {
+            smoothed.push((samples[i - 1] + samples[i + 1]) / 2);
+        }
+        samples = smoothed;
+    }
+
+    return arrayFastResample(samples, points);
+}
+
+/**
+ * Linearly maps the observed range of an array into a new inclusive range.
+ */
+export function arrayRescale(input: number[], newMin: number, newMax: number): number[] {
+    if (input.length === 0) return [];
+    const oldMin = Math.min(...input);
+    const oldMax = Math.max(...input);
+    if (oldMin === oldMax) return input.map(() => newMin);
+    const scale = (newMax - newMin) / (oldMax - oldMin);
+    return input.map(value => newMin + ((value - oldMin) * scale));
+}
